import { test, beforeEach, afterEach } from 'node:test';
import assert from 'node:assert/strict';
import { testServer } from './helpers.js';
import { createIssue } from '../src/modules/work/issues.js';
let server, api, project, org, user, sprint;
beforeEach(async () => {
  server = await testServer(); api = server.agent();
  user = (await api('POST', '/auth/signup', { name: 'Planner', email: 'planning@depth.test', password: 'correct-horse-battery' })).data.user;
  org = (await api('POST', '/orgs', { name: 'Planning depth' })).data.organization;
  project = (await api('POST', '/orgs/' + org.id + '/projects', { key: 'PLAN', name: 'Planning' })).data.project;
  sprint = (await api('POST', '/projects/' + project.id + '/sprints', { name: 'Current', startDate: '2026-10-01', endDate: '2026-10-20' })).data.sprint;
});
afterEach(async () => server.close());
const issue = (title, estimate = 3) => createIssue(server.ctx, { user }, project.id, { title, estimate });
test('project draft revision prevents stale metadata overwrites and returns authorized latest snapshot', async () => {
  const current = await api('PATCH', '/projects/' + project.id, { name: 'Remote project', expectedRevision: project.revision });
  const conflict = await api('PATCH', '/projects/' + project.id, { name: 'Local project', expectedRevision: project.revision });
  assert.equal(conflict.status, 409); assert.equal(conflict.data.error.details.current.name, 'Remote project');
  assert.equal((await api('GET', '/projects/' + project.id)).data.project.revision, current.data.project.revision);
});
test('workflow precondition protects stable IDs before replacing ordered statuses', async () => {
  await api('PATCH', '/projects/' + project.id, { description: 'Concurrent saved change' });
  const statuses = project.statuses.map(({ id, name, category }) => ({ id, name, category }));
  statuses[0].name = 'Local todo';
  assert.equal((await api('PUT', '/projects/' + project.id + '/workflow', { statuses, expectedRevision: project.revision })).status, 409);
  const result = await api('GET', '/projects/' + project.id + '/workflow');
  assert.equal(result.data.statuses[0].name, 'Todo'); assert.equal(result.data.statuses[0].id, project.statuses[0].id);
});
test('revision validation is backward compatible and rejects malformed preconditions', async () => {
  assert.equal((await api('PATCH', '/projects/' + project.id, { name: 'Allowed old client' })).status, 200);
  assert.equal((await api('PATCH', '/projects/' + project.id, { name: 'Bad', expectedRevision: 'invalid' })).status, 422);
});
test('denied project writes disclose no revision conflict snapshot', async () => {
  const guest = server.agent(); const id = (await guest('POST', '/auth/signup', { name: 'Guest', email: 'guest@depth.test', password: 'correct-horse-battery' })).data.user.id;
  await api('POST', '/orgs/' + org.id + '/members', { userId: id, role: 'guest' });
  await api('POST', '/projects/' + project.id + '/guests', { userId: id });
  const result = await guest('PATCH', '/projects/' + project.id, { name: 'Denied', expectedRevision: '0'.repeat(64) });
  assert.equal(result.status, 403); assert.equal(result.data.error.details?.current, undefined);
});
test('sprint revision changes when equal-sized scope is replaced, and rejects a stale start', async () => {
  const first = issue('First'), second = issue('Second');
  const added = (await api('POST', '/sprints/' + sprint.id + '/issues', { issueIds: [first.id], expectedRevision: sprint.revision })).data.sprint;
  await api('DELETE', '/sprints/' + sprint.id + '/issues/' + first.id);
  const replaced = (await api('POST', '/sprints/' + sprint.id + '/issues', { issueIds: [second.id] })).data.sprint;
  assert.equal(replaced.scopePoints, added.scopePoints); assert.notEqual(replaced.revision, added.revision);
  assert.equal((await api('POST', '/sprints/' + sprint.id + '/start', { expectedRevision: added.revision })).status, 409);
  assert.equal((await api('GET', '/sprints/' + sprint.id)).data.sprint.status, 'planned');
});
test('concurrent issue estimate updates invalidate sprint completion before historical publication', async () => {
  const work = issue('Mutable estimate');
  await api('POST', '/sprints/' + sprint.id + '/issues', { issueIds: [work.id] });
  const active = (await api('POST', '/sprints/' + sprint.id + '/start', {})).data.sprint;
  await api('PATCH', '/issues/' + work.id, { estimate: 8 });
  const stale = await api('POST', '/sprints/' + sprint.id + '/complete', { expectedRevision: active.revision });
  assert.equal(stale.status, 409); assert.equal(stale.data.error.details.current.remainingPoints, 8);
  assert.equal((await api('GET', '/sprints/' + sprint.id)).data.sprint.status, 'active');
});
test('eligible sprint search filters occupied issues before opaque pages without a total cap', async () => {
  const occupied = issue('Needle occupied');
  const other = (await api('POST', '/projects/' + project.id + '/sprints', { name: 'Other planned', startDate: '2026-10-21', endDate: '2026-10-30' })).data.sprint;
  await api('POST', '/sprints/' + other.id + '/issues', { issueIds: [occupied.id] });
  const ids = [];
  for (let n = 0; n < 213; n++) ids.push(issue('Needle ' + String(n).padStart(3, '0')).id);
  const found = [];
  let cursor;
  do {
    const page = await api('GET', '/sprints/' + sprint.id + '/candidates?' + new URLSearchParams({ q: 'Needle', limit: 17, ...(cursor ? { cursor } : {}) }));
    assert.equal(page.status, 200); assert.ok(page.data.items.length <= 17);
    found.push(...page.data.items.map(item => item.id)); cursor = page.data.nextCursor;
  } while (cursor);
  assert.deepEqual(new Set(found), new Set(ids)); assert.equal(found.includes(occupied.id), false);
});
test('current scope paging and metadata-only reads preserve canonical totals', async () => {
  const ids = Array.from({ length: 24 }, (_, n) => issue('Scope ' + n).id);
  await api('POST', '/sprints/' + sprint.id + '/issues', { issueIds: ids });
  const detail = await api('GET', '/sprints/' + sprint.id + '?scope=none');
  assert.equal(detail.data.issues.length, 0); assert.equal(detail.data.sprint.issueCount, 24);
  const page = await api('GET', '/sprints/' + sprint.id + '/scope?q=Scope&limit=5');
  assert.equal(page.data.items.length, 5); assert.ok(page.data.nextCursor); assert.equal(page.data.sprintRevision, detail.data.sprint.revision);
});
test('carry-over target search excludes active completed and foreign project sprints before paging', async () => {
  await api('POST', '/sprints/' + sprint.id + '/start', {});
  const next = (await api('POST', '/projects/' + project.id + '/sprints', { name: 'Target next', startDate: '2026-10-21', endDate: '2026-10-30' })).data.sprint;
  const result = await api('GET', '/sprints/' + sprint.id + '/carry-targets?q=Target&limit=1');
  assert.deepEqual(result.data.items.map(item => item.id), [next.id]);
  assert.equal((await api('POST', '/sprints/' + sprint.id + '/complete', { carryOverSprintId: sprint.id })).status, 422);
});
test('project and sprint list searches apply before page limits', async () => {
  const found = (await api('POST', '/orgs/' + org.id + '/projects', { key: 'FIND', name: 'Distinct target' })).data.project;
  assert.deepEqual((await api('GET', '/projects?q=Distinct&limit=1')).data.items.map(row => row.id), [found.id]);
  assert.deepEqual((await api('GET', '/projects/' + project.id + '/sprints?q=Current&limit=1')).data.items.map(row => row.id), [sprint.id]);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { createPlanningScope, selectedBoardIssues, bulkPreview } from '../src/pages/work/planning-actions.js';
import { uploadAttachment } from '../src/pages/work/attachment-state.js';
test('one scoped planning action admits no accidental duplicate while pending', () => {
  const scope = createPlanningScope(), first = scope.begin();
  assert.ok(first.current()); assert.equal(scope.begin(), null);
  first.finish(); assert.equal(first.current(), false); assert.ok(scope.begin()); scope.dispose();
});
test('navigation aborts old planning action and suppresses delayed completion', () => {
  const old = createPlanningScope(), request = old.begin(); old.dispose();
  assert.equal(request.signal.aborted, true); assert.equal(request.current(), false); assert.equal(old.begin(), null);
  const current = createPlanningScope(), newer = current.begin(); request.finish();
  assert.equal(newer.current(), true); current.dispose();
});
test('cancel belongs to current operation and old finally cannot clear the next one', () => {
  const scope = createPlanningScope(), old = scope.begin(); scope.cancel();
  assert.equal(old.signal.aborted, true); old.finish(); const next = scope.begin();
  old.finish(); assert.ok(next.current()); assert.equal(next.signal.aborted, false); scope.dispose();
});
test('bulk preview excludes hidden stale selections and identifies destructive intent', () => {
  const visible = selectedBoardIssues([{ issues: [{ id: 'visible', key: 'P-1' }] }], new Set(['visible', 'hidden']));
  const preview = bulkPreview(visible, { changes: { assigneeId: null, labelIds: [] } });
  assert.deepEqual(preview.ids, ['visible']); assert.equal(preview.destructive, true); assert.equal(preview.valid, true);
  assert.match(preview.summary, /clear assignees, clear every label/);
});
test('bulk preview prevents empty selection or unchanged fields from submitting', () => {
  assert.equal(bulkPreview([], { changes: { statusId: 'done' } }).valid, false);
  assert.equal(bulkPreview([{ id: 'one' }], { changes: {} }).valid, false);
  assert.equal(bulkPreview([{ id: 'one' }], { changes: {}, addLabelIds: ['label'] }).valid, true);
});
function transport() {
  return { upload: {}, open() {}, setRequestHeader() {}, send() {}, abort() { this.onabort?.(); } };
}
test('upload cancellation settles once even if old success and progress arrive later', async () => {
  const request = transport(), controller = new AbortController(), updates = [];
  const promise = uploadAttachment({ issueId: 'old', file: { name: 'old.bin', size: 3 }, signal: controller.signal, onProgress: value => updates.push(value), createRequest: () => request });
  const progress = request.upload.onprogress;
  controller.abort(); await assert.rejects(promise, error => error.code === 'CANCELLED');
  request.status = 201; request.responseText = JSON.stringify({ attachment: { name: 'old.bin' } }); request.onload();
  progress({ loaded: 3, lengthComputable: true, total: 3 });
  assert.equal(updates.length, 0); assert.equal(request.upload.onprogress, null);
});
test('delayed old upload cannot change a new resource upload controller or progress', async () => {
  const oldScope = createPlanningScope(), old = oldScope.begin();
  const oldRequest = transport(), nextRequest = transport(), notices = [];
  const oldPromise = uploadAttachment({ issueId: 'old', file: { name: 'old.bin', size: 1 }, signal: old.signal, createRequest: () => oldRequest }).catch(() => null);
  oldScope.dispose(); const nextScope = createPlanningScope(), next = nextScope.begin();
  const nextPromise = uploadAttachment({ issueId: 'next', file: { name: 'next.bin', size: 0 }, signal: next.signal, createRequest: () => nextRequest });
  oldRequest.status = 201; oldRequest.responseText = '{"attachment":{"name":"old.bin"}}'; oldRequest.onload();
  await oldPromise; old.finish(); assert.equal(next.current(), true); assert.equal(next.signal.aborted, false);
  nextRequest.status = 201; nextRequest.responseText = '{"attachment":{"name":"next.bin"}}'; nextRequest.onload();
  const value = await nextPromise; if (next.current()) notices.push(value.attachment.name);
  assert.deepEqual(notices, ['next.bin']); nextScope.dispose();
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { testServer } from '../../server/test/helpers.js';
import { createIssue } from '../../server/src/modules/work/issues.js';
async function browser(mode) {
  const server = await testServer(); let child;
  try {
    const api = server.agent();
    const auth = await api('POST', '/auth/signup', { name: 'Planning browser', email: 'planning-browser@example.test', password: 'correct-horse-battery' });
    const org = (await api('POST', '/orgs', { name: 'Planning browser' })).data.organization;
    const project = (await api('POST', '/orgs/' + org.id + '/projects', { key: 'PLAN', name: 'First planning project' })).data.project;
    const other = (await api('POST', '/orgs/' + org.id + '/projects', { key: 'NEXT', name: 'Second planning project' })).data.project;
    const issues = Array.from({ length: 24 }, (_, n) => createIssue(server.ctx, { user: auth.data.user }, project.id, { title: 'Planning issue ' + String(n).padStart(2, '0'), estimate: 3 }));
    const secondIssue = createIssue(server.ctx, { user: auth.data.user }, other.id, { title: 'Other resource issue' });
    const sprint = (await api('POST', '/projects/' + project.id + '/sprints', { name: 'First sprint', startDate: '2026-10-01', endDate: '2026-10-20' })).data.sprint;
    const next = (await api('POST', '/projects/' + project.id + '/sprints', { name: 'Next sprint', startDate: '2026-10-21', endDate: '2026-10-30' })).data.sprint;
    const settings = { mode, url: server.url, cookie: auth.cookie, projectId: project.id, otherId: other.id, issueId: issues[0].id, secondCard: issues[1].id, otherIssueId: secondIssue.id, activeId: project.statuses[1].id, sprintId: sprint.id, nextSprintId: next.id };
    const result = await new Promise((resolve, reject) => {
      child = spawn('/usr/bin/python3', [fileURLToPath(new URL('./planning-browser.py', import.meta.url)), JSON.stringify(settings)], { detached: true });
      let stdout = '', stderr = '';
      const timer = setTimeout(() => { try { process.kill(-child.pid, 'SIGKILL'); } catch {} reject(new Error('Planning browser exceeded 55 seconds')); }, 55000);
      child.stdout.on('data', value => stdout += value); child.stderr.on('data', value => stderr += value);
      child.on('error', error => { clearTimeout(timer); reject(error); });
      child.on('close', code => { clearTimeout(timer); resolve({ code, stdout, stderr }); });
    });
    assert.equal(result.code, 0, result.stderr + result.stdout); assert.equal(JSON.parse(result.stdout.trim()).ok, true);
    if (mode === 'planning') {
      const moved = (await api('GET', '/issues/' + issues[0].id)).data.issue;
      const ordered = (await api('GET', '/projects/' + project.id + '/board')).data.columns.find(column => column.status.id === project.statuses[1].id).issues;
      assert.equal(moved.statusId, project.statuses[1].id); assert.deepEqual(ordered.map(issue => issue.id), [issues[1].id, issues[0].id]);
      assert.equal((await api('GET', '/sprints/' + sprint.id)).data.sprint.status, 'active');
    } else {
      const oldFiles = (await api('GET', '/issues/' + issues[0].id + '/attachments')).data.items;
      const newFiles = (await api('GET', '/issues/' + secondIssue.id + '/attachments')).data.items;
      assert.ok(oldFiles.some(file => file.name === 'old-resource.txt'));
      assert.ok(newFiles.some(file => file.name === 'new-resource.txt'));
    }
  } finally { if (child?.pid) { try { process.kill(-child.pid, 'SIGKILL'); } catch {} } await server.close(); }
}
for (const mode of ['planning', 'upload']) test('pinned browser planning ' + mode + ' preserves resource lifecycle', { timeout: 65000 }, () => browser(mode));
